enum AttemptReason {
    Stop(AttemptStop),
    StopRule {
        quantity: QuantityId,
        body: u32,
        kind: Kind,
    },
    VerificationFailed,
    /// Exact H did not fit this row's published promise (escalates).
    PublicationEnclosure {
        quantity: QuantityId,
        body: u32,
        kind: Kind,
        predicate: PublicationPredicate,
    },
    /// D1 revision 5a.3 (R7 §4.1.6.3 item 13): `verification_estimate`.
    VerificationEstimate {
        quantity: QuantityId,
        body: u32,
        kind: Kind,
    },
    /// `uc`: a block with data of this body has neither Uc_c nor S_c.
    Uc {
        body: u32,
    },
    /// `theta`: θ_c > 1/2 on a block with data of this body.
    Theta {
        body: u32,
    },
    /// `g_validity`: a member in scope with g > 2^(P−16).
    GValidity {
        member: u32,
    },
    /// `charge`: C_q above its allowance.
    Charge {
        quantity: QuantityId,
        body: u32,
        kind: Kind,
    },
}

enum AttemptStop {
    Budget(BudgetScope),
    /// An exact sum exceeded the span limit (terminal: ROOT's ruling O4).
    Span,
    /// An exponent outside the `Wide` range (terminal).
    Exponent,
    /// Another `Wide` refusal (terminal; not expected for a valid source).
    Arithmetic(WideError),
    /// The sparse structure could not be built (terminal; internal).
    Structure,
    /// The pivot screen failed (escalates).
    Pivot {
        global_dof: usize,
    },
    /// A free DOF with an exactly zero diagonal (terminal).
    ZeroDiagonal {
        global_dof: usize,
    },
    /// A negative-energy pattern pair witnessed at p (terminal; a refusal).
    NegativeEnergy {
        i: usize,
        j: usize,
    },
    /// rcond ≤ 2^-(p−1) (escalates).
    Condition,
    /// The residual gate failed after bounded refinement (escalates).
    ResidualGate {
        global_dof: usize,
    },
    /// A body's formation scale E rounds to +∞ in binary64 (D1 revision
    /// 5a.3, R7 §4.1.6.2 item 4; ROOT's A3-0 ruling Q8): terminal.
    ResolutionScale {
        body: u32,
        kind: Kind,
    },
    /// The new publication certificate cannot be interpreted (terminal).
    PublicationCertificate {
        index: Option<usize>,
        issue: CertificateIssue,
    },
}

enum UnresolvedReason {
    /// "At the ceiling … the case is unresolved."
    Ceiling,
    Budget(BudgetScope),
    ExactSumSpan,
    ExponentRange,
    ZeroDiagonal {
        global_dof: usize,
    },
    Arithmetic(WideError),
    /// D1 revision 5a.3 (ROOT's A3-0 ruling Q8): a body's E rounds to +∞;
    /// F2a maps it to `receipt_encoding`.
    ResolutionScaleUnencodable {
        body: u32,
        kind: Kind,
    },
    /// A selected pair's B_b not below 2^1024 (R7 §4.1.6.3 item 14: derived
    /// impossible at a selected p; kept as a guard).
    CertifiedBoundUnencodable {
        body: u32,
    },
    PublicationCertificate {
        index: Option<usize>,
        issue: CertificateIssue,
    },
}

enum Refusal {
    MechanismWitnessed {
        body: u32,
        rigid_parameters: [f64; 6],
    },
    GeometryUnavailable {
        body: u32,
        error: StructuralError,
    },
    NegativeEnergy {
        i: usize,
        j: usize,
    },
    LedgerUnavailable(LedgerRefusal),
    Structure,
}

enum CombinationReason {
    /// "At the ceiling … `combination_unresolved`".
    CombinationUnresolved,
    /// No operand, or a non-finite factor.
    NoOperands,
    /// An operand is itself a combination.
    NestedCombination,
    /// The operands differ in stiffness identity, published layout, stations
    /// or support groups.
    OperandsDiffer,
    LedgerUnavailable(LedgerRefusal),
    /// Another terminal reason of the schedule (budget, span, exponent).
    Unresolved(UnresolvedReason),
    /// A terminal refusal of the schedule (not expected: the operands' factor
    /// passed).
    Refused(Refusal),
}

enum WideError {
    /// Precision outside [MIN_PRECISION, MAX_PRECISION] (or below
    /// ATAN_MIN_PRECISION for the arctangent).
    InvalidPrecision(u32),
    /// Lift of a NaN or infinity.
    NonFinite,
    /// A result exponent outside ±EXPONENT_LIMIT.
    ExponentRange,
    DivisionByZero,
    NegativeSqrt,
    /// `from_parts` with a significand that is neither zero nor normalized,
    /// or a zero with a nonzero exponent.
    NotNormalized,
    /// Arctangent argument outside its domain (t ≤ 0, s ≤ 0 or 1 + c ≤ 0).
    AngleDomain,
    /// Internal limit of the arctangent reached (unreachable by the proof).
    ArctangentLimit,
    /// Split of a value of magnitude 2^1024 or more.
    SplitOverflow,
    Accumulator(SumError),
    /// TwoSum or TwoProduct operand with more significant bits than the
    /// working precision (slice K3, `multi`).
    OperandPrecision,
}

