enum StructuralError {
    InvalidInput(&'static str),
    Range(&'static str),
    Asymmetric {
        row: usize,
        col: usize,
        relative_skew: f64,
    },
    NumericallyUnresolved {
        reason: &'static str,
        global_dof: Option<usize>,
    },
    NegativeEnergy {
        direction: Vec<f64>,
        energy: f64,
        allowance: f64,
    },
    Mechanism {
        direction: Vec<f64>,
    },
}

enum FrameKernelError {
    NonFiniteInput {
        name: &'static str,
        value: f64,
    },
    NonPositiveInput {
        name: &'static str,
        value: f64,
    },
    DegenerateAxis {
        detail: &'static str,
    },
    InvalidOrientation {
        detail: &'static str,
    },
    InvalidNodeIndex {
        node_index: usize,
        node_count: usize,
    },
    RepeatedElementNodeIndex {
        node_index: usize,
    },
    InvalidMatrixDimensions {
        rows: usize,
        cols: usize,
    },
    InvalidVectorLength {
        expected: usize,
        actual: usize,
    },
    RepeatedRestrainedDof {
        dof: usize,
    },
    RestrainedDofOutOfRange {
        dof: usize,
        total_dofs: usize,
    },
    RepeatedPrescribedDof {
        dof: usize,
    },
    PrescribedDofOutOfRange {
        dof: usize,
        total_dofs: usize,
    },
    SingularSystem {
        pivot: usize,
    },
    /// K2a (T3 D1 revision 5a.2 section 4.7, formation range, step 1): an
    /// intermediate product or quotient of `local_stiffness`, formed from
    /// nonzero finite operands, is zero, subnormal or non-finite in binary64.
    /// `name` names the coefficient and the intermediate. The formation is
    /// refused; it is never published as a zero or imprecise coefficient.
    NumericalRange {
        name: &'static str,
    },
}

enum ForceScaleReason {
    /// Step 2: a nonzero census input is subnormal; its bits were lost before
    /// the kernel.
    SubnormalAtFormation,
    /// Step 3: no (even) b fits the exponent span.
    InfeasibleWindow { e_min: i32, e_max: i32 },
    /// Step 4: the one evaluation at the chosen b also left the normal range.
    ScaledEvaluation,
    /// Step 5: a published action or reaction would underflow to zero or
    /// overflow after unscaling; it is never flushed. (A residual record's
    /// field carries its outcome instead: ROOT's K2b checkpoint-A ruling B.)
    PublicationOutsideBinary64 { global_dof: Option<usize> },
}

enum ForceScalingFailure {
    /// The orchestrator's named refusal (§4.7 steps 2-4), with its trigger.
    Refused(ForceScalingRefusal),
    /// A non-range failure at the chosen b, or of the census (RV11-N2). The
    /// orchestrator carries neither b nor the trigger (ROOT OQ1: c2).
    Failed(ForceScaledError),
    /// ROOT Q3: a family not admitted at b != 0.
    NotAdmitted { family: &'static str, b: i32 },
    /// §4.7 step 5: a published value that would underflow or overflow.
    Publication { quantity: String, b: i32 },
    /// Defensive: the orchestrator's step 1 did not reproduce the trigger.
    NotEngaged,
}
